#include <cstring>
#include <vector>
#include <cstdio>
#include <cmath>
#include <utility>
#include <queue>
#include <algorithm>
using namespace std;

class Hungary {
public:
    static const int SIZE = 2000;
    int cnt, pos[SIZE], rev[SIZE];
    int gao(int n, vector<int> e[]) {
        cnt = 0;
        fill(pos, pos + SIZE, -1);
        fill(rev, rev + SIZE, -1);
        for (int i = 0; i < n; i++) {
            fill(v, v + SIZE, 0);
            if (match(i, e)) cnt++;
        }
        return cnt;
    }
private:
    int v[SIZE];
    bool match(int x, vector<int> e[]) {
        for (int i = 0; i < (int)e[x].size(); i++) {
            int y = e[x][i];
            if (v[y]) continue;
            v[y] = 1;
            if (rev[y] < 0 || match(rev[y], e)) {
                pos[x] = y;
                rev[y] = x;
                return true;
            }
        }
        return false;
    }
};

const int INF = 1000000000;
const int dr[] = {0, -1, 0, 1};
const int dc[] = {1, 0, -1, 0};

int gridA[12][12], gridB[12][12], dist[12][12], rows, timeLimit;
vector<int> adj[2000];
vector<int> exits[12][12];

void bfs(int sr, int sc) {
    queue<int> qr, qc;
    fill(&dist[0][0], &dist[0][0] + 12 * 12, -1);
    qr.push(sr); qc.push(sc);
    dist[sr][sc] = 0;
    while (!qr.empty()) {
        sr = qr.front(); qr.pop();
        sc = qc.front(); qc.pop();
        for (int i = 0; i < 4; i++) {
            int nr = sr + dr[i], nc = sc + dc[i];
            if (gridA[nr][nc] >= 0 && dist[nr][nc] < 0) {
                dist[nr][nc] = dist[sr][sc] + 1;
                qr.push(nr); qc.push(nc);
            }
        }
    }
}

void propagate(int sr, int sc, int count) {
    int visited[12][12];
    queue<int> qr, qc;
    fill(&visited[0][0], &visited[0][0] + 12 * 12, -1);
    qr.push(sr); qc.push(sc);
    visited[sr][sc] = 0;
    while (!qr.empty()) {
        sr = qr.front(); qr.pop();
        sc = qc.front(); qc.pop();
        if (visited[sr][sc] > min(timeLimit, dist[sr][sc])) continue;
        for (int j = 0; j < (int)exits[sr][sc].size(); j++)
            for (int i = 0; i < count; i++)
                adj[rows + i].push_back(exits[sr][sc][j]);
        if (visited[sr][sc] == min(timeLimit, dist[sr][sc])) continue;
        for (int i = 0; i < 4; i++) {
            int nr = sr + dr[i], nc = sc + dc[i];
            if (gridA[nr][nc] >= 0 && visited[nr][nc] < 0) {
                visited[nr][nc] = visited[sr][sc] + 1;
                qr.push(nr); qc.push(nc);
            }
        }
    }
    rows += count;
}

Hungary solver;

int main() {
    int n, startR, startC, idx = rows = 0;
    scanf("%d%d", &n, &timeLimit);
    fill(&gridA[0][0], &gridA[0][0] + 12 * 12, -1);
    fill(&gridB[0][0], &gridB[0][0] + 12 * 12, -1);
    for (int i = 1; i <= n; i++) {
        while (getchar() != '\n');
        for (int j = 1; j <= n; j++) {
            char ch = getchar();
            if (ch >= '0' && ch <= '9') gridA[i][j] = ch - '0';
            if (ch == 'Z') { startR = i; startC = j; }
        }
    }
    bfs(startR, startC);
    while (getchar() != '\n');
    for (int i = 1; i <= n; i++) {
        while (getchar() != '\n');
        for (int j = 1; j <= n; j++) {
            char ch = getchar();
            if (ch >= '0' && ch <= '9') gridB[i][j] = ch - '0';
            for (int k = 0; k < gridB[i][j]; k++) exits[i][j].push_back(idx++);
        }
    }
    for (int i = 0; i < 12; i++) for (int j = 0; j < 12; j++)
        if (dist[i][j] < 0) dist[i][j] = INF;
    for (int i = 1; i <= n; i++) for (int j = 1; j <= n; j++)
        if (gridA[i][j] > 0) propagate(i, j, gridA[i][j]);
    printf("%d\n", solver.gao(rows, adj));
}
